const SPHINX = "sphinx";
const FREE_TYPES = 3;
const BASE_SCORE = 2;
const POINTS_PER_EXTRA_TYPE = 2;

const containsSphinx = (army: Card[]): boolean =>
  army.some((card) => card.monster === SPHINX);

const countTypesSeenBySphinx = (army: Card[]): number =>
  new Set(
    army.filter((card) => card.monster !== SPHINX).map((card) => card.monster),
  ).size;

export const scoreArmy = (army: Card[]): number => {
  if (!containsSphinx(army)) return 0;

  const typeCount = countTypesSeenBySphinx(army);
  if (typeCount <= FREE_TYPES) return BASE_SCORE;

  const extraTypes = typeCount - FREE_TYPES;
  return 1 + POINTS_PER_EXTRA_TYPE * extraTypes;
};
